TURN/STUN Relay Tier.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Person_Ext(web_mobile_client, "Web/Mobile Client", "Web and Mobile applications used by patients and clinicians.")
